import SwiftUI

enum Lang: String { case zh, en }

/// Resolve the tri-state language pref ("system" | "zh" | "en"): explicit
/// zh/en, else follow the SYSTEM language (zh for any Chinese locale, en
/// otherwise). The system value is read live so the app resolves again on
/// next launch when the OS language changes.
func resolveLangPref(_ pref: String) -> Lang {
    if pref == "zh" { return .zh }
    if pref == "en" { return .en }
    return Prefs.systemLangZh ? .zh : .en
}

@Observable
final class I18n {
    static let shared = I18n()
    var lang: Lang = .zh

    func set(_ l: Lang) { lang = l }

    func t(_ key: String, _ args: Any?...) -> String {
        var s = (lang == .zh ? zh[key] : nil) ?? en[key] ?? key
        for (i, a) in args.enumerated() {
            s = s.replacingOccurrences(of: "{arg\(i + 1)}", with: a.map { String(describing: $0) } ?? "")
        }
        return s
    }
}

func t(_ key: String, _ args: Any?...) -> String { I18n.shared.t(key, args) }

